<?php require 'vendor/autoload.php'; $app = require_once 'bootstrap/app.php'; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $faculty = App\Models\Faculty::where('full_name', 'like', '%Purvi%')->first(); if (!$faculty) { echo 'No Purvi found.'; } else { echo 'Purvi ID: ' . $faculty->id . "\n"; $assignments = App\Models\TeachingAssignment::with('subject')->where('faculty_id', $faculty->id)->get(); foreach ($assignments as $assignment) { echo $assignment->subject->subject_name . "\n"; } }
